def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    opp_budgets = []
    urgent_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            opp_budgets.append(opp.get('budget', 0))
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive:
        return max(0, min(budget, 18.0))

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / float(len(prev_bids)) if prev_bids else 0.0
    rich_opps = 0
    for b in opp_budgets:
        if b >= budget:
            rich_opps += 1

    tight_supply = supply <= 17
    ample_supply = supply >= 22
    critical_me = hp <= 3 or no_water_days >= 1
    very_safe = hp >= 8 and no_water_days == 0

    bid = 0.0

    if critical_me:
        if max_prev > 0:
            bid = max(72.0, min(max_prev + 2.5, DAILY_SALARY * 2.0))
        else:
            bid = 95.0
    elif tight_supply:
        if urgent_opp >= 2:
            bid = max(58.0, min(avg_prev * 0.72, 92.0))
        elif max_prev >= 120:
            bid = max(52.0, min(max_prev * 0.62, 88.0))
        else:
            bid = 54.0
    elif ample_supply:
        if very_safe:
            bid = 18.0
        else:
            bid = 28.0
    else:
        if max_prev >= 130:
            bid = 34.0 if very_safe else 46.0
        elif avg_prev >= 100:
            bid = 40.0
        else:
            bid = 32.0

    if rich_opps >= 3 and not critical_me and not tight_supply:
        bid *= 0.9

    if day >= 8:
        if hp >= 6 and no_water_days == 0:
            bid *= 0.9
        else:
            bid *= 1.1

    min_guard = 12.0 if very_safe else 20.0
    bid = max(min_guard, bid)
    bid = min(budget, bid)

    if budget < 25:
        bid = min(bid, budget)

    return max(0, float(round(bid, 2)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = day_context['day']

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids (immediate reaction only)
    yesterday_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Pressure estimate from yesterday
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    second_prev_bid = 0.0
    if len(yesterday_bids) >= 2:
        sorted_bids = sorted(yesterday_bids, reverse=True)
        second_prev_bid = float(sorted_bids[1])

    # Determine how urgent water is for me
    # If I'm already accumulating no-water days, I must secure water.
    urgent = (no_water_days >= 2) or (hp <= 2.5)

    # Estimate how many water units might be needed this day.
    # Supply is in [15,25]; with WATER_REQ=9, at most 2 units are feasible.
    # Use this to decide how competitive to be.
    max_units = int(supply / float(WATER_REQ))  # safe int conversion
    if max_units < 1:
        max_units = 1

    # Base bid policy: avoid overpaying unless urgent or yesterday showed extreme aggression.
    # Use highest_prev_bid to infer their willingness to pay.
    if urgent:
        # Bid to beat at least typical aggressive level but cap by budget.
        target = max(DAILY_SALARY * 0.75, second_prev_bid + 3.0)
        # If yesterday had very high bids, raise slightly.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = max(target, highest_prev_bid * 0.85)
    else:
        # Non-urgent: bid around a fraction of salary, adjusted by yesterday pressure.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # They are paying a lot; bid just above second tier.
            target = max(DAILY_SALARY * 0.45, second_prev_bid + 1.5)
        else:
            # Gentle participation.
            target = DAILY_SALARY * 0.5

        # If supply likely allows multiple winners, we can bid lower.
        if max_units >= 2:
            target *= 0.85

    # Ensure target is within budget and non-negative.
    target = max(0.0, float(target))
    bid = min(budget, target)

    # If budget is extremely low, still try to secure water when urgent.
    if budget <= DAILY_SALARY * 0.15:
        if urgent:
            bid = min(budget, DAILY_SALARY * 0.3)
        else:
            bid = min(budget, DAILY_SALARY * 0.12)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_budget, DAILY_SALARY * 0.1)

    base_bid = DAILY_SALARY * 0.65 

    # --- HP-based adjustments ---
    if my_hp <= 2: 
        base_bid = DAILY_SALARY * 0.95
    elif my_hp <= 4: 
        base_bid = DAILY_SALARY * 0.85
    elif my_hp >= 8: 
        base_bid = DAILY_SALARY * 0.5

    # --- End-game adjustments ---
    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2: 
        if my_hp <= 5: 
            base_bid = max(base_bid, DAILY_SALARY * 0.9)
        elif my_hp > 5 and my_budget < DAILY_SALARY: 
            base_bid = min(base_bid, DAILY_SALARY * 0.7)
    elif remaining_days <= 4: 
        if my_hp <= 3:
            base_bid = max(base_bid, DAILY_SALARY * 0.8)

    # --- Opponent reaction based on previous day's bids ---
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_hp <= 3: 
                base_bid = max(base_bid, highest_prev_bid + 1.0)
            elif my_hp >= 7: 
                base_bid = min(base_bid, DAILY_SALARY * 0.55)
            else: 
                base_bid = max(base_bid, highest_prev_bid * 1.02)
        elif highest_prev_bid >= DAILY_SALARY * 0.6:
            if my_hp <= 5: 
                base_bid = max(base_bid, highest_prev_bid + 1.0)
            else: 
                base_bid = max(base_bid, highest_prev_bid * 0.98)
        else:
            if my_hp <= 5: 
                base_bid = max(base_bid, highest_prev_bid + 1.0)
            else: 
                base_bid = min(base_bid, highest_prev_bid * 1.15)

    final_bid = min(my_budget, base_bid)

    if my_hp <= 5 and my_budget > 0:
        final_bid = max(final_bid, DAILY_SALARY * 0.15)

    if my_budget > 0 and my_hp <= 2:
        final_bid = max(final_bid, my_budget)

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive = len(alive_opponents)

    # Determine how many units of water can be allocated (each unit serves WATER_REQ)
    max_units = int(supply // WATER_REQ)

    # Check yesterday's traces for lowest max bid among alive opponents
    low_prev = None
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev and prev['bid'] is not None:
            if low_prev is None or prev['bid'] < low_prev:
                low_prev = prev['bid']

    # If desperate (low HP or no water), bid high
    desperate = hp <= 2 or no_water_days > 0

    if desperate:
        # Need water urgently: bid close to salary but ensure winning
        if max_units >= num_alive + 1:
            # Enough supply for all, bid low average
            base_bid = DAILY_SALARY * 0.4
        else:
            # Competition: bid enough to outbid lowest yesterday or a safe amount
            if low_prev is not None:
                base_bid = low_prev + 1.0
            else:
                base_bid = DAILY_SALARY * 0.75
        return min(budget, max(base_bid, DAILY_SALARY * 0.3))
    else:
        # Healthy: conserve budget
        # If low_prev is very low, we might still win with low bid
        if low_prev is not None and low_prev < DAILY_SALARY * 0.3:
            safe_bid = max(low_prev + 0.5, DAILY_SALARY * 0.15)
        else:
            safe_bid = DAILY_SALARY * 0.25
        return min(budget, safe_bid)
